import nested2tidy = require( './index' );


// TESTS //

// The function returns a data set...
{
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', [ 'x', 'y' ] ); // $ExpectType DataSet
}

// The compiler throws an error if the function is provided a first argument which is not an array-like object containing collections...
{
	nested2tidy( 5, 'data', [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( true, 'data', [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( false, 'data', [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( null, 'data', [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( {}, 'data', [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( ( x: number ): number => x, 'data', [ 'x', 'y' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a string...
{
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 5, [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], true, [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], false, [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], null, [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], [], [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], {}, [ 'x', 'y' ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], ( x: number ): number => x, [ 'x', 'y' ] ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not an array of strings...
{
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', 5 ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', true ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', false ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', null ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', {} ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', [ 1, 2 ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	nested2tidy(); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ] ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data' ); // $ExpectError
	nested2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', [ 'x', 'y' ], {} ); // $ExpectError
}
